import{_ as i,l,o as e,c as o,v as s,p as n,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"业务逻辑漏洞","description":"","frontmatter":{"title":"业务逻辑漏洞","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/business-logic-flaws.md","filePath":"cs/business-logic-flaws.md","lastUpdated":1789023840000}'),h={name:"cs/business-logic-flaws.md"};function _(u,a,E,f,m,A){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=s('<h1 id="业务逻辑漏洞" tabindex="-1">业务逻辑漏洞 <a class="header-anchor" href="#业务逻辑漏洞" aria-label="Permalink to &quot;业务逻辑漏洞&quot;">​</a></h1><div class="epigraph"><p>每一步都合法，合起来却破坏不变量：负数量、跳过支付、改价接口未授权。工具难自动找，因为错误在规格里，不在越界里。</p><footer>—— 据 OWASP 业务逻辑；Anderson 对激励与规则；对照[最小特权](/cs/acl-least-priv)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/web-race-condition">竞态</a>是并发不变量。缺口是<strong>规格本身</strong>：工作流。本课讲如何把不变量写成测试，不给欺诈剧本。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>优惠码可叠加到负价；状态机允许未付发货。缺口是：显式状态机、服务器侧计价、授权每一步。</p><h3 id="客体级授权" tabindex="-1">客体级授权 <a class="header-anchor" href="#客体级授权" aria-label="Permalink to &quot;客体级授权&quot;">​</a></h3><p>能调 API 不等于能碰该订单。BOLA 后课专收。</p><p><span class="marginnote">OWASP。禁止欺诈操作指导。撞库下一课是认证面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出不变量：价格非负、状态单调、资源属主。用属性测试。下一课撞库与速率。</p>',12)),(e(),n(p,null,{default:t(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E5%8D%95%E6%AD%A5%E5%90%88%E6%B3%95%22%5D%20--%3E%20COMP%5B%22%E7%BB%84%E5%90%88%E7%A0%B4%E5%9D%8F%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%0A%20%20INV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E4%BE%A7%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20--%3E%20ENF%5B%22%E6%AF%8F%E8%AF%B7%E6%B1%82%E5%BC%BA%E5%88%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=s('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>授权矩阵要覆盖工作流，不只登录。撞库是另一条：凭证已经泄漏，在你这重放。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写欺诈步骤。状态机不变量必须在服务器，不能只在前端。撞库与速率限制下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>竞态是时间；业务逻辑是规格。</li><li>不变量必须服务器强制。</li><li>工具对这类洞盲。</li><li>下一课撞库。</li><li>出处：OWASP Business Logic；Anderson；<a href="/cs/acl-least-priv">acl-least-priv</a>。</li></ul>',8))])}const P=i(h,[["render",_]]);export{B as __pageData,P as default};
